// every argument must hit two keyword groups
for (const a of args) {
  const hits = kw.filter(g => g.some(w => a.includes(w)));
  if (hits.length < 2) report(id, a);
}

// axios: attach once, not in every component
api.interceptors.request.use(cfg => {
  const t = localStorage.getItem('token');
  if (t) cfg.headers.Authorization = `Bearer ${t}`;
  return cfg;
});

